#include <cctype>
#include <string>
#include <vector>

namespace
{
    bool sep(char c) { return c == '\\' || c == '/'; }

    // The root as written, and how many characters of the path it takes.
    std::string rootOf(const std::string& p, std::size_t& used)
    {
        used = 0;
        if (p.size() >= 2 && std::isalpha(static_cast<unsigned char>(p[0])) && p[1] == ':')
        {
            if (p.size() >= 3 && sep(p[2])) { used = 3; return p.substr(0, 2) + "\\"; }
            used = 2;
            return p.substr(0, 2);
        }
        if (p.size() >= 2 && sep(p[0]) && sep(p[1]))
        {
            std::size_t i{ 2 };
            std::string server, share;
            while (i < p.size() && !sep(p[i])) server += p[i++];
            while (i < p.size() && sep(p[i])) ++i;
            while (i < p.size() && !sep(p[i])) share += p[i++];
            if (i < p.size()) ++i;
            used = i;
            return "\\\\" + server + "\\" + share + "\\";
        }
        if (!p.empty() && sep(p[0])) { used = 1; return "\\"; }
        return "";
    }
}

std::string pathRoot(const std::string& path) { std::size_t used; return rootOf(path, used); }

bool isAbsolute(const std::string& path)
{
    const std::string r{ pathRoot(path) };
    return r.size() >= 3 && (r[1] == ':' || r[0] == '\\');
}

std::string normalize(const std::string& path)
{
    std::size_t used{ 0 };
    const std::string root{ rootOf(path, used) };
    std::vector<std::string> parts;
    std::string part;
    auto flush = [&] {
        if (part.empty() || part == ".") { part.clear(); return; }
        if (part == "..")
        {
            if (!parts.empty() && parts.back() != "..") parts.pop_back();
            else if (root.empty()) parts.push_back("..");
        }
        else parts.push_back(part);
        part.clear();
    };
    for (std::size_t i{ used }; i < path.size(); ++i)
    {
        if (sep(path[i])) flush();
        else part += path[i];
    }
    flush();
    std::string out{ root };
    for (std::size_t i{ 0 }; i < parts.size(); ++i) out += (i ? "\\" : "") + parts[i];
    if (out.empty()) return ".";
    return out;
}

std::string join(const std::string& base, const std::string& more)
{
    const std::string r{ pathRoot(more) };
    if (r == "\\")
    {
        const std::string br{ pathRoot(base) };
        if (br.size() >= 2 && br[1] == ':') return normalize(br.substr(0, 2) + more);
        return normalize(more);
    }
    if (!r.empty()) return normalize(more);
    return normalize(base + "\\" + more);
}

std::string withLongPrefix(const std::string& path)
{
    const std::string n{ normalize(path) };
    if (n.size() < 260 || !isAbsolute(n)) return n;
    if (n[0] == '\\') return "\\\\?\\UNC\\" + n.substr(2);
    return "\\\\?\\" + n;
}

unitTests:
TEST("roots") {
    CHECK_EQ(pathRoot("C:\\x"), std::string("C:\\")); CHECK_EQ(pathRoot("d:/x"), std::string("d:\\")); CHECK_EQ(pathRoot("C:x"), std::string("C:"));
    CHECK_EQ(pathRoot("\\x"), std::string("\\")); CHECK_EQ(pathRoot("\\\\srv\\docs\\a.txt"), std::string("\\\\srv\\docs\\")); CHECK_EQ(pathRoot("notes\\a"), std::string(""));
    CHECK(isAbsolute("C:\\a")); CHECK(isAbsolute("\\\\srv\\docs")); CHECK(!isAbsolute("C:a")); CHECK(!isAbsolute("\\a")); CHECK(!isAbsolute("a"));
}
TEST("normalizing") {
    CHECK_EQ(normalize("C:/Users//Sam/./Docs/../notes.txt"), std::string("C:\\Users\\Sam\\notes.txt"));
    CHECK_EQ(normalize("C:\\..\\..\\Windows\\"), std::string("C:\\Windows")); CHECK_EQ(normalize("C:\\"), std::string("C:\\"));
    CHECK_EQ(normalize("..\\..\\x\\.\\y\\.."), std::string("..\\..\\x")); CHECK_EQ(normalize("a\\.."), std::string("."));
    CHECK_EQ(normalize("\\\\srv\\docs\\\\a\\..\\b"), std::string("\\\\srv\\docs\\b")); CHECK_EQ(normalize("\\\\srv\\docs\\.."), std::string("\\\\srv\\docs\\"));
}
TEST("joining") {
    CHECK_EQ(join("C:\\Users\\Sam", "Docs\\a.txt"), std::string("C:\\Users\\Sam\\Docs\\a.txt")); CHECK_EQ(join("C:\\Users\\Sam\\", "..\\Ana"), std::string("C:\\Users\\Ana"));
    CHECK_EQ(join("C:\\Users", "D:\\Data"), std::string("D:\\Data")); CHECK_EQ(join("C:\\Users\\Sam", "\\Windows"), std::string("C:\\Windows"));
    CHECK_EQ(join("C:\\a", "\\\\srv\\s\\f"), std::string("\\\\srv\\s\\f"));
}
TEST("long paths") {
    const std::string longDir = "C:\\" + std::string(300, 'x');
    CHECK_EQ(withLongPrefix(longDir), "\\\\?\\" + longDir); CHECK_EQ(withLongPrefix("C:\\short"), std::string("C:\\short"));
    const std::string unc = "\\\\srv\\share\\" + std::string(260, 'y'); CHECK_EQ(withLongPrefix(unc), "\\\\?\\UNC\\srv\\share\\" + std::string(260, 'y'));
    CHECK_EQ(withLongPrefix(std::string(300, 'z')), std::string(300, 'z'));
}

